import{_ as t,a0 as o,w as d,s as c,ao as l,I as i,a1 as e,A as p,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 React 條件渲染中使用三元表達式和 “&&” | LCTT x X-CMD","titleTemplate":false,"description":"在 React 條件渲染中使用三元表達式和 “&&” | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 React 條件渲染中使用三元表達式和 “&&” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 React 條件渲染中使用三元表達式和 “&&” | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180201 Conditional Rendering in React using Ternaries and","title":"在 React 條件渲染中使用三元表達式和 “&&”","tag":"201810","desc":""},"relativePath":"201810/20180201 Conditional Rendering in React using Ternaries and.md","filePath":"[post].md"}'),r={name:"201810/20180201 Conditional Rendering in React using Ternaries and.md"};function g(h,s,u,m,k,b){const n=o("Link");return d(),c("div",null,[s[20]||(s[20]=l(`<h1 id="在-react-條件渲染中使用三元表達式和" tabindex="-1">在 React 條件渲染中使用三元表達式和 “&amp;&amp;” <a class="header-anchor" href="#在-react-條件渲染中使用三元表達式和" aria-label="Permalink to “在 React 條件渲染中使用三元表達式和 “&amp;&amp;””">​</a></h1><p><img src="https://cdn-images-1.medium.com/max/2000/1*eASRJrCIVgsy5VbNMAzD9w.jpeg" alt=""></p><p>React 組件可以通過多種方式決定渲染內容。你可以使用傳統的 <code>if</code> 語句或 <code>switch</code> 語句。在本文中，我們將探討一些替代方案。但要注意，如果你不小心，有些方案會帶來自己的陷阱。</p><h3 id="三元表達式-vs-if-else" tabindex="-1">三元表達式 vs if/else <a class="header-anchor" href="#三元表達式-vs-if-else" aria-label="Permalink to “三元表達式 vs if/else”">​</a></h3><p>假設我們有一個組件被傳進來一個 <code>name</code> 屬性。 如果這個字符串非空，我們會顯示一個問候語。否則，我們會告訴用户他們需要登錄。</p><p>這是一個只實現瞭如上功能的無狀態函數式組件（SFC）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name }) =&gt; {</span></span>
<span class="line"><span>  if (name) {</span></span>
<span class="line"><span>    return (</span></span>
<span class="line"><span>      &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>        Hello {name}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  return (</span></span>
<span class="line"><span>    &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>      Please sign in</span></span>
<span class="line"><span>    &lt;/div&gt;</span></span>
<span class="line"><span>  );</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>這個很簡單但是我們可以做得更好。這是使用<ruby>三元運算符<rt>conditional ternary operator</rt></ruby>編寫的相同組件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name }) =&gt; (</span></span>
<span class="line"><span>  &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    {name ? \`Hello \${name}\` : &#39;Please sign in&#39;}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>請注意這段代碼與上面的例子相比是多麼簡潔。</p><p>有幾點需要注意。因為我們使用了箭頭函數的單語句形式，所以隱含了<code>return</code> 語句。另外，使用三元運算符允許我們省略掉重複的 <code>&lt;div className=&quot;hello&quot;&gt;</code> 標記。</p><h3 id="三元表達式-vs" tabindex="-1">三元表達式 vs &amp;&amp; <a class="header-anchor" href="#三元表達式-vs" aria-label="Permalink to “三元表達式 vs &amp;&amp;”">​</a></h3><p>正如您所看到的，三元表達式用於表達 <code>if</code>/<code>else</code> 條件式非常好。但是對於簡單的 <code>if</code> 條件式怎麼樣呢？</p><p>讓我們看另一個例子。如果 <code>isPro</code>（一個布爾值）為真，我們將顯示一個獎盃表情符號。我們也要渲染星星的數量（如果不是 0）。我們可以這樣寫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name, isPro, stars}) =&gt; (</span></span>
<span class="line"><span>  &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    &lt;div&gt;</span></span>
<span class="line"><span>      Hello {name}</span></span>
<span class="line"><span>      {isPro ? &#39;♨&#39; : null}</span></span>
<span class="line"><span>    &lt;/div&gt;</span></span>
<span class="line"><span>    {stars ? (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        Stars:{&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    ) : null}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>請注意 <code>else</code> 條件返回 <code>null</code> 。 這是因為三元表達式要有“否則”條件。</p><p>對於簡單的 <code>if</code> 條件式，我們可以使用更合適的東西：<code>&amp;&amp;</code> 運算符。這是使用 <code>&amp;&amp;</code> 編寫的相同代碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name, isPro, stars}) =&gt; (</span></span>
<span class="line"><span>  &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    &lt;div&gt;</span></span>
<span class="line"><span>      Hello {name}</span></span>
<span class="line"><span>      {isPro &amp;&amp; &#39;♨&#39;}</span></span>
<span class="line"><span>    &lt;/div&gt;</span></span>
<span class="line"><span>    {stars &amp;&amp; (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        Stars:{&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    )}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>沒有太多區別，但是注意我們消除了每個三元表達式最後面的 <code>: null</code> （<code>else</code> 條件式）。一切都應該像以前一樣渲染。</p><p>嘿！約翰得到了什麼？當什麼都不應該渲染時，只有一個 <code>0</code>。這就是我上面提到的陷阱。這裏有解釋為什麼：</p>`,20)),i("p",null,[e(n,{href:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Logical_Operators"},{default:p(()=>[...s[0]||(s[0]=[a("根據 MDN",-1)])]),_:1}),s[1]||(s[1]=a("，一個邏輯運算符“和”（也就是 ",-1)),s[2]||(s[2]=i("code",null,"&&",-1)),s[3]||(s[3]=a("）：",-1))]),s[21]||(s[21]=l(`<blockquote><p><code>expr1 &amp;&amp; expr2</code></p></blockquote><blockquote><p>如果 <code>expr1</code> 可以被轉換成 <code>false</code> ，返回 <code>expr1</code>；否則返回 <code>expr2</code>。 如此，當與布爾值一起使用時，如果兩個操作數都是 <code>true</code>，<code>&amp;&amp;</code> 返回 <code>true</code> ；否則，返回 <code>false</code>。</p></blockquote><p>好的，在你開始拔頭髮之前，讓我為你解釋它。</p><p>在我們這個例子裏， <code>expr1</code> 是變量 <code>stars</code>，它的值是 <code>0</code>，因為 0 是假值，<code>0</code> 會被返回和渲染。看，這還不算太壞。</p><p>我會簡單地這麼寫。</p><blockquote><p>如果 <code>expr1</code> 是假值，返回 <code>expr1</code> ，否則返回 <code>expr2</code>。</p></blockquote><p>所以，當對非布爾值使用 <code>&amp;&amp;</code> 時，我們必須讓這個假值返回 React 無法渲染的東西，比如説，<code>false</code> 這個值。</p><p>我們可以通過幾種方式實現這一目標。讓我們試試吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{!!stars &amp;&amp; (</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    {&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>)}</span></span></code></pre></div><p>注意 <code>stars</code> 前的雙感嘆操作符（<code>!!</code>）（呃，其實沒有雙感嘆操作符。我們只是用了感嘆操作符兩次）。</p><p>第一個感嘆操作符會強迫 <code>stars</code> 的值變成布爾值並且進行一次“非”操作。如果 <code>stars</code> 是 <code>0</code> ，那麼 <code>!stars</code> 會是 <code>true</code>。</p><p>然後我們執行第二個<code>非</code>操作，所以如果 <code>stars</code> 是 <code>0</code>，<code>!!stars</code> 會是 <code>false</code>。正好是我們想要的。</p><p>如果你不喜歡 <code>!!</code>，那麼你也可以強制轉換出一個布爾數比如這樣（這種方式我覺得有點冗長）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{Boolean(stars) &amp;&amp; (</span></span></code></pre></div><p>或者只是用比較符產生一個布爾值（有些人會説這樣甚至更加語義化）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{stars &gt; 0 &amp;&amp; (</span></span></code></pre></div><h4 id="關於字符串" tabindex="-1">關於字符串 <a class="header-anchor" href="#關於字符串" aria-label="Permalink to “關於字符串”">​</a></h4><p>空字符串與數字有一樣的毛病。但是因為渲染後的空字符串是不可見的，所以這不是那種你很可能會去處理的難題，甚至可能不會注意到它。然而，如果你是完美主義者並且不希望 DOM 上有空字符串，你應採取我們上面對數字採取的預防措施。</p><h3 id="其它解決方案" tabindex="-1">其它解決方案 <a class="header-anchor" href="#其它解決方案" aria-label="Permalink to “其它解決方案”">​</a></h3><p>一種可能的將來可擴展到其他變量的解決方案，是創建一個單獨的 <code>shouldRenderStars</code> 變量。然後你用 <code>&amp;&amp;</code> 處理布爾值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const shouldRenderStars = stars &gt; 0;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>return (</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    {shouldRenderStars &amp;&amp; (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        {&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    )}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>之後，在將來，如果業務規則要求你還需要已登錄，擁有一條狗以及喝淡啤酒，你可以改變 <code>shouldRenderStars</code> 的得出方式，而返回的內容保持不變。你還可以把這個邏輯放在其它可測試的地方，並且保持渲染明晰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const shouldRenderStars = </span></span>
<span class="line"><span>  stars &gt; 0 &amp;&amp; loggedIn &amp;&amp; pet === &#39;dog&#39; &amp;&amp; beerPref === &#39;light\`;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>return (</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    {shouldRenderStars &amp;&amp; (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        {&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    )}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>我認為你應該充分利用這種語言。對於 JavaScript，這意味着為 <code>if/else</code> 條件式使用三元表達式，以及為 <code>if</code> 條件式使用 <code>&amp;&amp;</code> 操作符。</p><p>我們可以回到每處都使用三元運算符的舒適區，但你現在消化了這些知識和力量，可以繼續前進 <code>&amp;&amp;</code> 取得成功了。</p><hr><p>作者簡介：</p>`,30)),i("p",null,[s[5]||(s[5]=a("美國運通工程Blog的執行編輯 ",-1)),e(n,{href:"http://aexp.io"},{default:p(()=>[...s[4]||(s[4]=[a("http://aexp.io",-1)])]),_:1}),s[6]||(s[6]=a(" 以及 @AmericanExpress 的工程總監。MyViews !== ThoseOfMyEmployer.",-1))]),s[22]||(s[22]=i("hr",null,null,-1)),i("p",null,[s[8]||(s[8]=a("via: ",-1)),e(n,{href:"https://medium.freecodecamp.org/conditional-rendering-in-react-using-ternaries-and-logical-and-7807f53b6935"},{default:p(()=>[...s[7]||(s[7]=[a("https://medium.freecodecamp.org/conditional-rendering-in-react-using-ternaries-and-logical-and-7807f53b6935",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),e(n,{href:"https://medium.freecodecamp.org/@donavon"},{default:p(()=>[...s[9]||(s[9]=[a("Donavon West",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),e(n,{href:"https://github.com/GraveAccent"},{default:p(()=>[...s[10]||(s[10]=[a("GraveAccent",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const y=t(r,[["render",g]]);export{C as __pageData,y as default};
